<?php declare(strict_types=1);namespace StudPulse\Http;use StudPulse\Database\DB;use StudPulse\Domain\{Input,Access};use StudPulse\Security\Auth;final class ReportController{public function create(Auth$a,Request$r):array{$type=Input::text($r->body,'targetType',30);$id=Input::id($r->body['targetId']??null)??'';if($type==='homework'){$a->require('homework:read');Access::homework($a,$id);}elseif($type==='material'){$a->require('materials:read');Access::material($a,$id);}else{throw new ApiError(422,'VALIDATION','Допустимы homework/material');}$report=DB::id();DB::run('INSERT INTO content_reports(id,user_id,target_type,target_id,reason) VALUES(?,?,?,?,?)',[$report,$a->user['id'],$type,$id,Input::text($r->body,'reason',500)]);return['id'=>$report,'message'=>'Обращение сохранено для оператора проекта'];}}